/* stars.h: the star field — 12 dim stars behind everything, turning with
 * the dome (M5 Task 2). The stars are the Vectrex's stars.s table mapped
 * to the Neo Geo screen by the task's formulas (x0, y in
 * build/stars_map.h, generated by tools/render_stars.py); each frame every
 * star sits at
 *
 *     x = (x0 - round(dome_angle * 320 / 240)) mod 320,  y = y0
 *
 * so one dome turn scrolls the stars one whole screen width, leftward as
 * dome_angle grows (the Vectrex relationship). The pure half, stars_pos,
 * is built for the host (tests/stars_sim) and held to tests/stars_model.py
 * for every star and every dome_angle.
 *
 * The hardware half draws each star as one 1-tile sprite in sprite slots
 * 1..NSTARS (STAR_SPRITE, slots.h) — the LOWEST slots, so the stars sit
 * behind the dome, the missiles, the overlays, the ship and the HUD
 * (a higher slot draws on top). The picture is a 16x16 tile holding a 2x2
 * dot at its top-left in colour index 1 (STAR_TILE_BASE, one tile after
 * the broken sheet), so the sprite's X and Y ARE the dot's. Each star has
 * its own palette (STAR_PAL_BASE + i), colour (120, 130, 160): with one
 * bank per star a star's dot can never be recoloured by another star's
 * palette.
 *
 * The sprites are never shrunk: SCB2 is written once at init (0x0fff) and
 * only X/Y/height change per frame, so the per-frame cost is 2 words per
 * star (3 with the initial SCB4). The HUD rows are FIXMAP tiles, which sit
 * under every sprite, so the fix-layer text covers a star that scrolls
 * under it (fine: the task says the HUD may cover the stars).
 */
#ifndef STARS_H
#define STARS_H
#include <ngdevkit/types.h>
#include "slots.h"               /* STAR_SPRITE, NSTARS: the lowest slots */
#include "stars_map.h"           /* star_x0 / star_y / STAR_TILE_BASE (build) */

#define STAR_PAL_BASE 8          /* 12 free banks: 0..7 are used (text,
                                  * dome, ship, missile, bullet, explosion,
                                  * broken, hud) */

/* the pure position (the task's formula). dome_angle 0..239. */
void stars_pos(u8 i, u8 dome_angle, u16 *x, u8 *y);

void stars_init(void);           /* palettes + the tile + SCB2 (once) */
void stars_show(u8 dome_angle);  /* once per frame: every star's X and Y */
void stars_hide(void);           /* every star slot SCB3 0 (the title: the
                                  * Vectrex's title_screen draws no stars) */
#endif
